;\n  right: 0;\n  z-index: 100; // below top-matter and top-bar\n  cursor: ns-resize;\n  opacity: 0;\n  transition:\n    opacity 0.2s ease-in-out,\n    visibility 0.2s ease-in-out;\n\n  // Show on hover or scroll of main window\n  &:hover,\n  &.scrolling-recycler {\n    opacity: 1;\n    visibility: visible;\n  }\n\n  // On phone, there is no point of hover, so just hide it when not scrolling\n  @include phone {\n    visibility: hidden;\n  }\n\n  > .ticks-container {\n    pointer-events: none;\n  }\n\n  > .ticks-container > .tick {\n    pointer-events: none;\n    position: absolute;\n    font-size: 0.75em;\n    line-height: 0.75em;\n    font-weight: 600;\n    opacity: 0.95;\n    right: 9px;\n    top: 0;\n    transition: transform 0.2s linear;\n    z-index: 1;\n\n    &.dash {\n      height: 4px;\n      width: 4px;\n      border-radius: 50%;\n      background-color: var(--color-main-text);\n      opacity: 0.15;\n      display: block;\n      @include phone {\n        display: none;\n      }\n    }\n\n    @include phone {\n      background-color: var(--color-main-background);\n      padding: 4px;\n      border-radius: 4px;\n    }\n  }\n\n  > .cursor {\n    position: absolute;\n    pointer-events: none;\n    right: 0;\n    background-color: var(--color-primary);\n    min-width: 100%;\n    min-height: 1.5px;\n    will-change: transform;\n\n    &.st {\n      font-size: 0.75em;\n      opacity: 0;\n    }\n\n    &.hv {\n      background-color: var(--color-main-background);\n      padding: 1px 5px;\n      border-bottom: 2px solid var(--color-primary);\n      border-radius: 2px;\n      width: auto;\n      white-space: nowrap;\n      z-index: 100;\n      font-size: 0.95em;\n      font-weight: 600;\n      height: calc(1.2em + 10px);\n\n      > .icon {\n        display: none;\n        color: var(--color-main-text);\n        opacity: 0.75;\n\n        :deep > .menu-up-icon {\n          transform: translate(-3px, 4px);\n        }\n        :deep > .menu-down-icon {\n          transform: translate(-3px, -6px);\n        }\n      }\n    }\n  }\n  &.scrolling-recycler-now:not(.scrolling-now) > .cursor {\n    transition: transform 0.1s linear;\n  }\n  &:hover > .cursor {\n    transition: none !important;\n    &.st {\n      opacity: 1;\n    }\n  }\n\n  // Hide ticks on mobile unless hovering\n  @include phone {\n    // Shift pointer events to hover cursor\n    pointer-events: none;\n    .cursor.hv {\n      pointer-events: all;\n    }\n\n    > .ticks-container > .tick {\n      right: 40px;\n    }\n    &:not(.scrolling) {\n      > .ticks-container {\n        display: none;\n      }\n    }\n\n    .cursor.hv {\n      left: 6px;\n      border: none;\n      box-shadow: -1px 2px 11px -5px #000;\n      height: 44px;\n      width: 44px;\n      border-radius: 22px;\n      > .text {\n        display: none;\n      }\n      > .icon {\n        display: block;\n      }\n    }\n\n    .cursor.st {\n      display: none;\n    }\n  }\n}\n"],"sourceRoot":""}]);
