\n}\n\n// Flags to show on timeline\n.flag {\n  position: absolute;\n  z-index: 100;\n  pointer-events: none;\n  transition: transform 0.15s ease;\n  color: white;\n  display: flex;\n\n  &.top-right {\n    top: var(--icon-dist);\n    right: var(--icon-dist);\n    .p-outer.selected > & {\n      transform: translate(-$icon-size, $icon-size);\n    }\n  }\n\n  &.bottom-left {\n    bottom: var(--icon-dist);\n    left: var(--icon-dist);\n    .p-outer.selected > & {\n      transform: translate($icon-size, -$icon-size);\n    }\n  }\n\n  &.bottom-right {\n    bottom: var(--icon-dist);\n    right: var(--icon-dist);\n    .p-outer.selected > & {\n      transform: translate(-$icon-size, -$icon-size);\n    }\n  }\n\n  > .shared-by {\n    font-size: 0.75em;\n    line-height: 0.75em;\n    font-weight: 400;\n    margin: 2px;\n  }\n\n  > .video {\n    display: flex;\n    line-height: 22px; // force text height to match\n\n    > .time {\n      font-size: 0.75em;\n      font-weight: bold;\n      margin-right: 3px;\n    }\n  }\n\n  > .livephoto {\n    pointer-events: auto; // hover to play\n  }\n  > .raw {\n    height: 22px; // force height to match\n  }\n}\n\n// Actual image\ndiv.img-outer {\n  position: relative;\n  box-sizing: border-box;\n  padding: 0;\n  cursor: pointer;\n\n  transition: padding 0.15s ease;\n  .p-outer.selected > & {\n    padding: calc(var(--icon-dist) + $icon-half-size);\n  }\n\n  .p-outer.placeholder > & {\n    background-color: var(--color-background-dark);\n    background-clip: content-box, padding-box;\n  }\n\n  > .ximg {\n    background-clip: content-box;\n    object-fit: cover;\n    z-index: 1;\n    background-color: var(--color-background-dark);\n\n    -webkit-tap-highlight-color: transparent;\n    -webkit-touch-callout: none;\n    pointer-events: none;\n    transition:\n      border-radius 0.1s ease-in,\n      transform 0.3s ease-in-out;\n\n    .p-outer.placeholder > & {\n      display: none;\n    }\n    .p-outer.error & {\n      object-fit: contain;\n    }\n  }\n\n  > video {\n    pointer-events: none;\n    object-fit: cover;\n    z-index: 2;\n  }\n\n  > .overlay {\n    pointer-events: none;\n    z-index: 3;\n    background: linear-gradient(180deg, rgba(0, 0, 0, 0.2) 0%, transparent 30%);\n\n    display: none;\n    transition: border-radius 0.1s ease-in;\n    @media (hover: hover) and (pointer: fine) {\n      .p-outer:not(.selected):hover > & {\n        display: block;\n      }\n    }\n  }\n\n  > * {\n    @media (max-width: 768px) {\n      .selected > & {\n        border-radius: $icon-size;\n        border-top-left-radius: 0;\n      }\n    }\n  }\n}\n"],"sourceRoot":""}]);
